// Derivative entry (ad.entry/v1) of mpas_sw_aerosol_levels, the RRTMG SW aerosol-optics level pass
// (MPAS module_ra_rrtmg_sw_aerosols.F:70-451 calc_aerosol_rrtmg_sw, :453-837 the RH-interpolated spectral tables,
// :890-921 calc_relative_humidity; driver mpas_atmphys_driver_radiation_sw.F:529-583).
// Forward: captured source 3c499c7b lines 3878-3900 (hexcore/mpasphys/rrtmg_sw_v842.py:3559-3581), image c22c485e,
// launched once per SW aerosol call from rrtmg_sw_v842.py:443-446 (_aerosol_passes), grid ceil(nc*nl/64), block 64,
// one thread per (column c, radiation level k < nl).
// Per (c, k < nz), rh = clamp(100 e/es, 0, 99) with e = 0.01 max(qv,0) p/(max(qv,0)+0.62197),
// es = 6.112 exp(17.6 tc/(tc+243.5)), tc = t-273.15, and per band b (14 SW bands):
//   tau[c,b,k] = has3d ? (angopt==3 ? S_RAOD(rh)*aod3[c,k] : <not written>) : spectral[c,b]/denom[c]*dz[c,k]*exp(-zs[c,k]/2500)
//   ssa[c,b,k] = ssaopt==3 ? S_SSA(rh) : (ssaopt==1 ? ssaval : ssa2[c])
//   asy[c,b,k] = asyopt==3 ? S_ASY(rh) : (asyopt==1 ? asyval : asy2[c])
//   slope[c,k] = (diag&1 && angopt==3) ? 0.25/c0 * sum_{b=7..10} x_b log(has3d ? tau/aod3 : spectral/aod2) : <not written>
// where S_T(rh) = sum_{j in window(rh)} L_j(rh) T[type-1][j][b] is the Lagrange interpolation (up to 6 nodes) of table
// T over the RH nodes MPAS_RHS = {0,50,70,80,90,95,98,99}. k >= nz writes the constants tau=0, ssa=1, asy=0.
// Active: p, t, qv (through rh) and aod3; on the other option paths also dz, zs, spectral, denom, aod2, ssa2, asy2 (in).
// tau, ssa, asy are out (full overwrite of the c < nc rows); slope is out where the forward writes it. type is an
// integer table index (inactive).
// Frozen coefficients (limiter-like branches, each taken from the trajectory in __tl and __ad; RESULT.md hazards):
//   F1  rv = max(0, qv)                (forward 3767): drv/dqv = (qv > 0) ? 1 : 0.
//   F2  rh = min(99, max(0, raw))      (forward 3770): drh/draw = (0 < raw < 99) ? 1 : 0.
//   F3  the window index ii            (forward 3774-3775): the node window [imin, imax] is fixed at the primal rh and
//       the interpolant is differentiated as the polynomial of that window (dL_j/drh in closed form).
// Refused (failure[0] |= 2, nothing written): has3d && angopt != 3. The forward then leaves tau unwritten and, per its
// own comment (capture source 3782-3786), the native path reads indeterminate aod550spc3d; there is no derivative of
// indeterminate storage to write. hrrrv5 runs has3d=1, angopt=ssaopt=asyopt=3, diag=0 (every captured launch).
// Precision (the glue-row rule, as the live schemes): __aug repeats the forward word for word in f32 (__f*_rn and the
// glibc-transcribed gfk_exp/gfk_log above, built --fmad=false --ftz=false) and is bitwise to the forward image.
// __tl/__ad recompute the f32 primal words (rh, es, raw, tau, q1, exp) exactly as the forward, form every local
// partial in double, and round once to f32 per written word. Column-shared adjoints (spectral, denom, aod2, ssa2,
// asy2) are summed in double over the column's levels before their one rounding.
// Determinism: __tl is one thread per (c, k) as the forward, each owning its 3x14 output words and slope[c,k].
// __ad runs each column serially in its k == 0 thread (forward geometry; threads k > 0 return), so column-shared
// accumulations have a fixed order and there are no float atomics. The only atomic is the failure-flag OR:
// bit 0 a non-finite derivative word (or the log of a non-positive value on the slope path), bit 1 the refused config.
// ===================================================================================================================
#define SAL_C0 0x1.15bd6p-3f

__device__ __forceinline__ void sal_flag(int* failure, double v) { if (!isfinite(v)) atomicOr(failure, 1); }
// Round once to f32; + 0.0 turns a -0 product of a zero tangent into +0 (exact zero bits for the zero direction).
__device__ __forceinline__ float sal_w(double v) { return (float)(v + 0.0); }

struct SalRh { float rh, raw, es, tc; bool pass_rh, pass_q; };
// The forward's mpas_sw_rh, operation for operation, keeping the words the partials need.
__device__ __forceinline__ SalRh sal_rh(float p, float t, float qv)
{
    SalRh r;
    r.tc = FSUB(t, 273.15f);
    const float rv = fmaxf(0.f, qv);
    r.es = FMUL(6.112f, gfk_exp(FDIV(FMUL(17.6f, r.tc), FADD(r.tc, 243.5f))));
    const float e = FDIV(FMUL(FMUL(.01f, rv), p), FADD(rv, .62197f));
    r.raw = FDIV(FMUL(100.f, e), r.es);
    r.rh = fminf(99.f, fmaxf(0.f, r.raw));
    r.pass_q = qv > 0.f;                         // F1
    r.pass_rh = r.raw > 0.f && r.raw < 99.f;     // F2
    return r;
}
// d raw / d(p, t, qv) in double at the primal words (raw = 100 * 0.01 rv p / (rv + eps) / es, es = 6.112 exp(A)).
__device__ __forceinline__ void sal_rh_partials(float p, float qv, const SalRh& r, double* dp, double* dt, double* dq)
{
    if (!r.pass_rh) { *dp = 0.0; *dt = 0.0; *dq = 0.0; return; }
    const double rv = r.pass_q ? (double)qv : 0.0;
    const double eps = (double).62197f, c100 = 100.0 * (double).01f, den = rv + eps, es = (double)r.es;
    const double a = (double)r.tc + (double)243.5f;
    *dp = c100 * (rv / den) / es;
    *dq = r.pass_q ? c100 * (double)p * eps / (den * den) / es : 0.0;
    *dt = -(double)r.raw * ((double)17.6f * (double)243.5f / (a * a));
}
// F3: the forward's node window at the primal rh.
__device__ __forceinline__ void sal_stencil(float rh, int* imin, int* imax)
{
    int ii = 0; while (ii < 8 && rh > MPAS_RHS[ii]) ii++;
    *imin = max(0, ii - 3); *imax = min(7, ii + 2);
}
// Lagrange basis L_j(x) and dL_j/dx on the frozen window, in double (product rule along the forward's k order).
__device__ __forceinline__ void sal_lagrange(double x, int imin, int imax, double* L, double* dL)
{
    for (int j = imin; j <= imax; j++) {
        double l = 1.0, dl = 0.0;
        for (int k = imin; k <= imax; k++) if (k != j) {
            const double den = (double)MPAS_RHS[j] - (double)MPAS_RHS[k];
            const double f = (x - (double)MPAS_RHS[k]) / den;
            dl = dl * f + l / den;
            l *= f;
        }
        L[j - imin] = l; dL[j - imin] = dl;
    }
}
__device__ __forceinline__ void sal_interp(const float table[3][8][14], int ty, int b, int imin, int imax,
                                           const double* L, const double* dL, double* S, double* Sp)
{
    double s = 0.0, sp = 0.0;
    for (int j = imin; j <= imax; j++) { const double T = (double)table[ty][j][b]; s += L[j - imin] * T; sp += dL[j - imin] * T; }
    *S = s; *Sp = sp;
}
__device__ const float SAL_FOLDED_X[4] = {0x1.373cep-1f, 0x1.f2935p-3f, -0x1.fab97ep-6f, -0x1.57c8d6p-2f};

// The forward (capture source 3c499c7b:3878-3900) word for word, plus the failure flag (bit 0: a non-finite word).
extern "C" __global__ void mpas_sw_aerosol_levels__aug(int nc,int nz,int nl,int has3d,int angopt,int ssaopt,int asyopt,
 float ssaval,float asyval,int diagnostic_mask,const float* p,const float* t,const float* qv,const float* dz,
 const int* type,const float* aod2,const float* aod3,const float* ssa2,const float* asy2,
 const float* spectral,const float* zs,const float* denom,float* tau,float* ssa,float* asy,float* slope,int* failure) {
 const long long g=(long long)blockIdx.x*blockDim.x+threadIdx.x;if(g>=(long long)nc*nl)return;
 const long long c=g/nl;const int k=(int)(g-c*nl);
 if(k>=nz){for(int b=0;b<14;b++){long long i=(c*14+b)*nl+k;tau[i]=0.f;ssa[i]=1.f;asy[i]=0.f;}return;}
 const long long ck=c*nz+k;
 float rh=mpas_sw_rh(p[ck],t[ck],qv[ck]);
 float xy=0.f,xx=0.f;
 for(int b=0;b<14;b++){
  long long i=(c*14+b)*nl+k;
  if(!has3d)tau[i]=FMUL(FMUL(FDIV(spectral[c*14+b],denom[c]),dz[ck]),gfk_exp(FDIV(-zs[ck],2500.f)));
  else if(angopt==3)tau[i]=mpas_sw_spectral(MPAS_RAOD,type[c],b,rh,aod3[ck],true);
  ssa[i]=ssaopt==3?mpas_sw_spectral(MPAS_SSA,type[c],b,rh,0.f,false):(ssaopt==1?ssaval:ssa2[c]);
  asy[i]=asyopt==3?mpas_sw_spectral(MPAS_ASY,type[c],b,rh,0.f,false):(asyopt==1?asyval:asy2[c]);
  if((diagnostic_mask&1)&&angopt==3&&b>=7&&b<=10){
   const float folded_x[4]={0x1.373cep-1f,0x1.f2935p-3f,-0x1.fab97ep-6f,-0x1.57c8d6p-2f};
   float x=folded_x[b-7];
   float value=has3d?FDIV(tau[i],aod3[ck]):FDIV(spectral[c*14+b],aod2[c]);
   xy=FADD(xy,FMUL(x,gfk_log(value)));xx=FADD(xx,FMUL(x,x));
  }
  if(!isfinite(ssa[i])||!isfinite(asy[i])||((!has3d||angopt==3)&&!isfinite(tau[i])))atomicOr(failure,1);
 }
 if((diagnostic_mask&1)&&angopt==3){slope[ck]=FDIV(FMUL(xy,.25f),0x1.15bd6p-3f);if(!isfinite(slope[ck]))atomicOr(failure,1);}
}

extern "C" __global__ void mpas_sw_aerosol_levels__tl(
    int nc, int nz, int nl, int has3d, int angopt, int ssaopt, int asyopt, float ssaval, float asyval, int diagnostic_mask,
    const float* __restrict__ p, const float* __restrict__ t, const float* __restrict__ qv, const float* __restrict__ dz,
    const int* __restrict__ type, const float* __restrict__ aod2, const float* __restrict__ aod3,
    const float* __restrict__ spectral, const float* __restrict__ zs, const float* __restrict__ denom,
    const float* __restrict__ d_p, const float* __restrict__ d_t, const float* __restrict__ d_qv,
    const float* __restrict__ d_dz, const float* __restrict__ d_aod2, const float* __restrict__ d_aod3,
    const float* __restrict__ d_ssa2, const float* __restrict__ d_asy2, const float* __restrict__ d_spectral,
    const float* __restrict__ d_zs, const float* __restrict__ d_denom,
    float* __restrict__ o_tau, float* __restrict__ o_ssa, float* __restrict__ o_asy, float* __restrict__ o_slope,
    int* __restrict__ failure)
{
    const long long g = (long long)blockIdx.x * blockDim.x + threadIdx.x; if (g >= (long long)nc * nl) return;
    const long long c = g / nl; const int k = (int)(g - c * nl);
    if (has3d && angopt != 3) { atomicOr(failure, 2); return; }
    if (k >= nz) { for (int b = 0; b < 14; b++) { long long i = (c * 14 + b) * nl + k; o_tau[i] = 0.f; o_ssa[i] = 0.f; o_asy[i] = 0.f; } return; }
    const long long ck = c * nz + k;
    const SalRh r = sal_rh(p[ck], t[ck], qv[ck]);
    double rp, rt, rq; sal_rh_partials(p[ck], qv[ck], r, &rp, &rt, &rq);
    const double drh = rp * (double)d_p[ck] + rt * (double)d_t[ck] + rq * (double)d_qv[ck];
    int imin, imax; sal_stencil(r.rh, &imin, &imax);
    double L[6], dL[6]; sal_lagrange((double)r.rh, imin, imax, L, dL);
    const int ty = type[c] - 1;
    const bool slope_on = (diagnostic_mask & 1) && angopt == 3;
    double dxy = 0.0;
    for (int b = 0; b < 14; b++) {
        const long long i = (c * 14 + b) * nl + k;
        double dtau; float tauw = 0.f;
        if (!has3d) {
            const float q1 = FDIV(spectral[c * 14 + b], denom[c]);
            const float E = gfk_exp(FDIV(-zs[ck], 2500.f));
            tauw = FMUL(FMUL(q1, dz[ck]), E);
            const double D = (double)denom[c];
            dtau = ((double)d_spectral[c * 14 + b] / D - (double)q1 / D * (double)d_denom[c]) * (double)dz[ck] * (double)E
                 + (double)q1 * (double)E * (double)d_dz[ck] - (double)tauw * (double)d_zs[ck] / 2500.0;
        } else {
            double S, Sp; sal_interp(MPAS_RAOD, ty, b, imin, imax, L, dL, &S, &Sp);
            dtau = Sp * (double)aod3[ck] * drh + S * (double)d_aod3[ck];
            if (slope_on && b >= 7 && b <= 10) tauw = mpas_sw_spectral(MPAS_RAOD, type[c], b, r.rh, aod3[ck], true);
        }
        o_tau[i] = sal_w(dtau); sal_flag(failure, dtau);
        double ds = 0.0, da = 0.0;
        if (ssaopt == 3) { double S, Sp; sal_interp(MPAS_SSA, ty, b, imin, imax, L, dL, &S, &Sp); ds = Sp * drh; }
        else if (ssaopt != 1) ds = (double)d_ssa2[c];
        if (asyopt == 3) { double S, Sp; sal_interp(MPAS_ASY, ty, b, imin, imax, L, dL, &S, &Sp); da = Sp * drh; }
        else if (asyopt != 1) da = (double)d_asy2[c];
        o_ssa[i] = sal_w(ds); o_asy[i] = sal_w(da); sal_flag(failure, ds); sal_flag(failure, da);
        if (slope_on && b >= 7 && b <= 10) {
            const double x = (double)SAL_FOLDED_X[b - 7];
            float value; double dv;
            if (has3d) { value = FDIV(tauw, aod3[ck]); dv = (dtau - (double)value * (double)d_aod3[ck]) / (double)aod3[ck]; }
            else { value = FDIV(spectral[c * 14 + b], aod2[c]);
                   dv = ((double)d_spectral[c * 14 + b] - (double)value * (double)d_aod2[c]) / (double)aod2[c]; }
            if (!(value > 0.f)) atomicOr(failure, 1);
            dxy += x * dv / (double)value;
        }
    }
    if (slope_on) { const double ds = dxy * 0.25 / (double)SAL_C0; o_slope[ck] = sal_w(ds); sal_flag(failure, ds); }
}

// Reverse. Output seeds (tau, ssa, asy everywhere; slope where the forward writes it) are read and consumed (set 0);
// the inputs accumulate. One thread (k == 0) per column walks the column's levels in order; per-level inputs get one
// rounding each, column-shared inputs one rounding after the loop.
extern "C" __global__ void mpas_sw_aerosol_levels__ad(
    int nc, int nz, int nl, int has3d, int angopt, int ssaopt, int asyopt, float ssaval, float asyval, int diagnostic_mask,
    const float* __restrict__ p, const float* __restrict__ t, const float* __restrict__ qv, const float* __restrict__ dz,
    const int* __restrict__ type, const float* __restrict__ aod2, const float* __restrict__ aod3,
    const float* __restrict__ spectral, const float* __restrict__ zs, const float* __restrict__ denom,
    float* __restrict__ b_p, float* __restrict__ b_t, float* __restrict__ b_qv, float* __restrict__ b_dz,
    float* __restrict__ b_aod2, float* __restrict__ b_aod3, float* __restrict__ b_ssa2, float* __restrict__ b_asy2,
    float* __restrict__ b_spectral, float* __restrict__ b_zs, float* __restrict__ b_denom,
    float* __restrict__ b_tau, float* __restrict__ b_ssa, float* __restrict__ b_asy, float* __restrict__ b_slope,
    int* __restrict__ failure)
{
    const long long g = (long long)blockIdx.x * blockDim.x + threadIdx.x; if (g >= (long long)nc * nl) return;
    const long long c = g / nl; if (g - c * nl != 0) return;
    if (has3d && angopt != 3) { atomicOr(failure, 2); return; }
    const int ty = type[c] - 1;
    const bool slope_on = (diagnostic_mask & 1) && angopt == 3;
    double a_spec[14], a_denom = 0.0, a_aod2 = 0.0, a_ssa2 = 0.0, a_asy2 = 0.0;
    for (int b = 0; b < 14; b++) a_spec[b] = 0.0;
    for (int k = 0; k < nl; k++) {
        if (k >= nz) {
            for (int b = 0; b < 14; b++) { long long i = (c * 14 + b) * nl + k; b_tau[i] = 0.f; b_ssa[i] = 0.f; b_asy[i] = 0.f; }
            continue;
        }
        const long long ck = c * nz + k;
        const SalRh r = sal_rh(p[ck], t[ck], qv[ck]);
        double rp, rt, rq; sal_rh_partials(p[ck], qv[ck], r, &rp, &rt, &rq);
        int imin, imax; sal_stencil(r.rh, &imin, &imax);
        double L[6], dL[6]; sal_lagrange((double)r.rh, imin, imax, L, dL);
        double g_rh = 0.0, a_aod3 = 0.0, a_dz = 0.0, a_zs = 0.0, bxy = 0.0;
        if (slope_on) { bxy = (double)b_slope[ck] * 0.25 / (double)SAL_C0; b_slope[ck] = 0.f; }
        for (int b = 0; b < 14; b++) {
            const long long i = (c * 14 + b) * nl + k;
            double bt = (double)b_tau[i];
            const double bs = (double)b_ssa[i], ba = (double)b_asy[i];
            b_tau[i] = 0.f; b_ssa[i] = 0.f; b_asy[i] = 0.f;
            if (slope_on && b >= 7 && b <= 10) {   // slope reads the tau word linearly: its seed joins bt first
                const double x = (double)SAL_FOLDED_X[b - 7];
                if (has3d) {
                    const float tauw = mpas_sw_spectral(MPAS_RAOD, type[c], b, r.rh, aod3[ck], true);
                    const float value = FDIV(tauw, aod3[ck]);
                    if (!(value > 0.f)) atomicOr(failure, 1);
                    const double bv = bxy * x / (double)value;
                    bt += bv / (double)aod3[ck];
                    a_aod3 -= bv * (double)value / (double)aod3[ck];
                } else {
                    const float value = FDIV(spectral[c * 14 + b], aod2[c]);
                    if (!(value > 0.f)) atomicOr(failure, 1);
                    const double bv = bxy * x / (double)value;
                    a_spec[b] += bv / (double)aod2[c];
                    a_aod2 -= bv * (double)value / (double)aod2[c];
                }
            }
            if (!has3d) {
                const float q1 = FDIV(spectral[c * 14 + b], denom[c]);
                const float E = gfk_exp(FDIV(-zs[ck], 2500.f));
                const float tauw = FMUL(FMUL(q1, dz[ck]), E);
                const double D = (double)denom[c];
                a_spec[b] += bt * (double)dz[ck] * (double)E / D;
                a_denom -= bt * (double)q1 * (double)dz[ck] * (double)E / D;
                a_dz += bt * (double)q1 * (double)E;
                a_zs -= bt * (double)tauw / 2500.0;
            } else {
                double S, Sp; sal_interp(MPAS_RAOD, ty, b, imin, imax, L, dL, &S, &Sp);
                g_rh += bt * Sp * (double)aod3[ck];
                a_aod3 += bt * S;
            }
            if (ssaopt == 3) { double S, Sp; sal_interp(MPAS_SSA, ty, b, imin, imax, L, dL, &S, &Sp); g_rh += bs * Sp; }
            else if (ssaopt != 1) a_ssa2 += bs;
            if (asyopt == 3) { double S, Sp; sal_interp(MPAS_ASY, ty, b, imin, imax, L, dL, &S, &Sp); g_rh += ba * Sp; }
            else if (asyopt != 1) a_asy2 += ba;
        }
        const double ap = rp * g_rh, at = rt * g_rh, aq = rq * g_rh;
        sal_flag(failure, ap); sal_flag(failure, at); sal_flag(failure, aq); sal_flag(failure, a_aod3);
        b_p[ck] = sal_w((double)b_p[ck] + ap);
        b_t[ck] = sal_w((double)b_t[ck] + at);
        b_qv[ck] = sal_w((double)b_qv[ck] + aq);
        if (has3d) b_aod3[ck] = sal_w((double)b_aod3[ck] + a_aod3);
        else {
            sal_flag(failure, a_dz); sal_flag(failure, a_zs);
            b_dz[ck] = sal_w((double)b_dz[ck] + a_dz);
            b_zs[ck] = sal_w((double)b_zs[ck] + a_zs);
        }
    }
    if (!has3d) {
        for (int b = 0; b < 14; b++) { sal_flag(failure, a_spec[b]); b_spectral[c * 14 + b] = sal_w((double)b_spectral[c * 14 + b] + a_spec[b]); }
        sal_flag(failure, a_denom); b_denom[c] = sal_w((double)b_denom[c] + a_denom);
        if (slope_on) { sal_flag(failure, a_aod2); b_aod2[c] = sal_w((double)b_aod2[c] + a_aod2); }
    }
    if (ssaopt != 3 && ssaopt != 1) { sal_flag(failure, a_ssa2); b_ssa2[c] = sal_w((double)b_ssa2[c] + a_ssa2); }
    if (asyopt != 3 && asyopt != 1) { sal_flag(failure, a_asy2); b_asy2[c] = sal_w((double)b_asy2[c] + a_asy2); }
}
